update public.spell_catalog set
name_ru='Нанесение ран', casting_time='Действие', spell_range='Касание', area='1 существо', duration='Мгновенно', components=array['В','С'], material=null, check_type='Спасбросок Телосложения', damage='2к10 некротическим; половина при успехе', effect_summary='Касанием насылаешь некротическую энергию. Цель получает урон при провале и половину при успехе.', upcast='+1к10 урона за каждый уровень ячейки выше 1.', notes='Требует касания цели.', author_description='Жрец касается человека, и тот начинает умирать быстрее. Очень удобно для класса, который пять минут назад объяснял всем ценность жизни.', author_comment='Воин хотя бы честно приходит с мечом.' where slug='inflict-wounds';

update public.spell_catalog set
name_ru='Прыжок', casting_time='Бонусное действие', spell_range='Касание', area='1 согласное существо', duration='1 минута', components=array['В','С','М'], material='задняя лапка кузнечика', check_type='', damage='', effect_summary='Раз за каждый свой ход цель может потратить 10 футов перемещения и прыгнуть на расстояние до 30 футов.', upcast='+1 цель за каждый уровень ячейки выше 1.', notes='Требует согласную цель.', author_description='Ты превращаешь нормального человека в человека, который внезапно считает тридцатифутовый прыжок разумным способом перемещения. Следопыты используют это для дела. Волшебники — чтобы потом срочно вспоминать Падение пёрышком.', author_comment='Если прыжок кажется слишком далёким, значит ты ещё не посмотрел вниз.' where slug='jump';

update public.spell_catalog set
name_ru='Длинный шаг', casting_time='Действие', spell_range='Касание', area='1 существо', duration='1 час', components=array['В','С','М'], material='щепотка земли', check_type='', damage='', effect_summary='Скорость цели увеличивается на 10 футов на время действия.', upcast='+1 цель за каждый уровень ячейки выше 1.', notes='Не требует концентрации.', author_description='Простое и полезное заклинание: идёшь быстрее целый час. Следопыты понимают ценность сразу. Маги обычно только после того, как выясняется, что лошадь умерла, а портал почему-то не готов.', author_comment='Десять лишних футов скорости часто отделяют «ушёл» от «его доедают».' where slug='longstrider';

update public.spell_catalog set
name_ru='Доспех мага', casting_time='Действие', spell_range='Касание', area='1 согласное существо без брони', duration='8 часов', components=array['В','С','М'], material='кусочек выделанной кожи', check_type='', damage='', effect_summary='Базовый КД цели становится 13 + модификатор Ловкости.', upcast='', notes='Работает только на цель без надетой брони. Заклинание заканчивается раньше, если цель надевает броню.', author_description='Магический доспех для людей, которые принципиально не хотят носить настоящий. Восемь часов иллюзии безопасности за одну ячейку. Академическая традиция, видимо.', author_comment='Воин решает ту же проблему металлом и без расхода магии.' where slug='mage-armor';

update public.spell_catalog set
name_ru='Волшебная стрела', casting_time='Действие', spell_range='120 футов', area='До трёх выбранных целей', duration='Мгновенно', components=array['В','С'], material=null, check_type='Без броска атаки и спасброска', damage='3 снаряда по 1к4 + 1 силового каждый', effect_summary='Создаёт три магических снаряда, которые автоматически попадают по видимым целям в пределах дистанции. Можно распределить между одной или несколькими целями.', upcast='+1 снаряд за каждый уровень ячейки выше 1.', notes='Все снаряды попадают одновременно. Щит полностью защищает от Волшебной стрелы.', author_description='Три снаряда, никаких бросков атаки, никаких оправданий про плохие кости. Волшебники наконец создали оружие, которое не требует от них меткости.', author_comment='Если даже это не попало — значит кто-то вовремя произнёс «Щит».' where slug='magic-missile';

update public.spell_catalog set
name_ru='Защита от зла и добра', casting_time='Действие', spell_range='Касание', area='1 согласное существо', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='флакон святой воды стоимостью 25+ зм, расходуется', check_type='', damage='', effect_summary='Защищает цель от аберраций, небожителей, элементалей, фей, исчадий и нежити: их атаки по цели идут с Помехой, они не могут очаровать, испугать или одержать её.', upcast='', notes='Если цель уже Очарована, Испугана или одержима существом подходящего типа, она получает Преимущество на новые спасброски против соответствующего эффекта.', author_description='Очень конкретная страховка от существ, которых обычно описывают словами «не трогай», «не вызывай» и «почему варлок опять улыбается». Дороговато, зато список неприятностей впечатляет.', author_comment='Если вам понадобилась эта защита, хороший момент спросить, кто именно притащил сюда исчадие.' where slug='protection-from-evil-and-good';

update public.spell_catalog set
name_ru='Очищение еды и питья', casting_time='Действие', spell_range='10 футов', area='Сфера радиусом 5 футов', duration='Мгновенно', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Удаляет яд и гниль из немагической еды и питья в области.', upcast='', notes='Ритуал. Работает только на немагическую еду и питьё.', author_description='Превращает подозрительный ужин обратно в еду. Незаменимо в дороге, дешёвых тавернах и после того, как плут сказал: «Да нормально пахнет».', author_comment='Если суп пережил это заклинание, возможно, его всё-таки можно есть.' where slug='purify-food-and-drink';

update public.spell_catalog set
name_ru='Луч болезни', casting_time='Действие', spell_range='60 футов', area='1 существо', duration='Мгновенно', components=array['В','С'], material=null, check_type='Дальняя атака заклинанием', damage='2к8 ядом', effect_summary='При попадании наносит 2к8 ядом и даёт цели состояние Отравленный до конца твоего следующего хода.', upcast='+1к8 урона за каждый уровень ячейки выше 1.', notes='Состояние Отравленный применяется только при попадании.', author_description='Зелёный луч, яд и временное отравление. Волшебники иногда пытаются объяснить, почему это считается некромантией. Никто не спрашивал.', author_comment='Не спорь о школе магии с человеком, который только что выстрелил в тебя болезнью.' where slug='ray-of-sickness';

update public.spell_catalog set
name_ru='Убежище', casting_time='Бонусное действие', spell_range='30 футов', area='1 существо', duration='1 минута', components=array['В','С','М'], material='осколок зеркала', check_type='Спасбросок Мудрости у атакующего', damage='', effect_summary='Любой, кто хочет атаковать защищённую цель или выбрать её целью наносящего урон заклинания, должен пройти спасбросок Мудрости; при провале выбирает новую цель или теряет атаку/заклинание.', upcast='', notes='Не защищает от областей. Заканчивается, если защищённая цель атакует, колдует или наносит урон.', author_description='На минуту ты становишься настолько неприятной целью, что врагам приходится магически убеждать себя тебя ударить. Работает, пока ты сам не решишь снова участвовать в драке.', author_comment='Идеально для жреца, который хочет стоять сзади и иметь на это официальный документ.' where slug='sanctuary';

update public.spell_catalog set
name_ru='Пылающая кара', casting_time='Бонусное действие сразу после попадания оружием ближнего боя или безоружным ударом', spell_range='На себя', area='Цель только что попавшей атаки', duration='1 минута', components=array['В'], material=null, check_type='Спасбросок Телосложения в начале каждого хода цели после урона', damage='+1к6 огнём при попадании и 1к6 огнём в начале каждого хода цели', effect_summary='После попадания цель загорается. В начале каждого её хода получает 1к6 огнём и затем делает спасбросок Телосложения; успех заканчивает заклинание.', upcast='Весь урон увеличивается на 1к6 за каждый уровень ячейки выше 1.', notes='Не требует концентрации.', author_description='Паладин бьёт цель, после чего она продолжает гореть по религиозным причинам. Не знаю, насколько это способствует обращению в веру, но спорить люди после такого действительно начинают меньше.', author_comment='Аргумент с продолжительным эффектом.' where slug='searing-smite';

update public.spell_catalog set
name_ru='Щит', casting_time='Реакция, когда по тебе попали атакой или тебя выбрала целью Волшебная стрела', spell_range='На себя', area='Ты', duration='1 раунд', components=array['В','С'], material=null, check_type='', damage='', effect_summary='До начала твоего следующего хода получаешь +5 КД, включая против спровоцировавшей атаки, и не получаешь урон от Волшебной стрелы.', upcast='', notes='Срабатывает после попадания, но бонус КД применяется и к этой атаке.', author_description='Магический барьер появляется ровно в тот момент, когда маг внезапно вспоминает, что не хочет получать по лицу. Пожалуй, одна из самых искренних школ магии.', author_comment='Пять КД — цена внезапного осознания собственной смертности.' where slug='shield';

update public.spell_catalog set
name_ru='Щит веры', casting_time='Бонусное действие', spell_range='60 футов', area='1 существо', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='молитвенный свиток', check_type='', damage='', effect_summary='Цель получает +2 КД на время действия.', upcast='', notes='Требует концентрации.', author_description='Жрец просит высшие силы сделать кого-то сложнее для попадания. На удивление, +2 КД приходят быстрее, чем ответ на большинство молитв.', author_comment='Если бог занят, возможно, свиток просто напомнил ему, что вы ещё живы.' where slug='shield-of-faith';

update public.spell_catalog set
name_ru='Безмолвный образ', casting_time='Действие', spell_range='60 футов', area='Иллюзия до куба 15 футов', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='кусочек шерсти', check_type='Интеллект (Расследование) против Сл спасброска заклинаний при изучении', damage='', effect_summary='Создаёт чисто визуальную иллюзию объекта, существа или явления размером до куба 15 футов. Действием Магии можно перемещать и естественно изменять её движение.', upcast='', notes='Нет звука, запаха и других ощущений. Физический контакт раскрывает иллюзию. Успешное изучение позволяет видеть сквозь неё.', author_description='Создаёшь убедительную картинку, пока никто не решит потрогать её или спросить, почему огромный дракон совершенно бесшумен. Полезно, если у противника воображение быстрее логики.', author_comment='Иллюзия хороша ровно до первого человека, который решит пройти через стену.' where slug='silent-image';

update public.spell_catalog set
name_ru='Сон', casting_time='Действие', spell_range='60 футов', area='Сфера радиусом 5 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='щепотка песка или лепестков роз', check_type='Два спасброска Мудрости', damage='', effect_summary='Выбранные существа в области при первом провале становятся Недееспособными до конца своего следующего хода и затем повторяют спасбросок. Второй провал делает цель Бессознательной на оставшееся время.', upcast='', notes='Урон или действие существа в 5 футах, которое будит цель, заканчивает эффект на ней. Существа, которые не спят, и существа с иммунитетом к Истощению автоматически преуспевают.', author_description='Сначала человек перестаёт нормально действовать, потом, если снова не повезло, засыпает посреди боя. Великолепное напоминание, что режим сна — тоже оружие.', author_comment='Если враг уснул в бою, не буди его речью барда. Есть более гуманные способы.' where slug='sleep';

update public.spell_catalog set
name_ru='Разговор с животными', casting_time='Действие', spell_range='На себя', area='Ты', duration='10 минут', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Можешь понимать зверей, разговаривать с ними и использовать против них варианты навыков действия Влияние. Они могут сообщить сведения о местах и чудовищах, замеченных за последние сутки.', upcast='', notes='Ритуал. Большинство зверей мало знает о вещах, не связанных с выживанием и отношениями.', author_description='На десять минут ты получаешь возможность спросить у местной живности, что здесь происходило. Следопыты используют это как разведку. Друиды — как очередной повод утверждать, что у них много друзей.', author_comment='Если крыса оказалась самым информированным свидетелем в городе, город заслужил крысу.' where slug='speak-with-animals';

update public.spell_catalog set
name_ru='Громовая волна', casting_time='Действие', spell_range='На себя', area='Куб 15 футов, исходящий от тебя', duration='Мгновенно', components=array['В','С'], material=null, check_type='Спасбросок Телосложения', damage='2к8 звуком; половина при успехе', effect_summary='При провале цель получает 2к8 звукового урона и отталкивается на 10 футов. Незакреплённые предметы в области тоже отбрасывает.', upcast='+1к8 урона за каждый уровень ячейки выше 1.', notes='Грохот слышен на расстоянии до 300 футов. При успешном спасброске цель не отталкивается.', author_description='Ты создаёшь настолько громкий удар, что врагов и мебель физически отбрасывает от тебя. Скрытность после этого считается завершённой по взаимному согласию.', author_comment='Хорошее заклинание, если план засады уже всё равно испорчен.' where slug='thunderwave';

update public.spell_catalog set
name_ru='Невидимый слуга', casting_time='Действие', spell_range='60 футов', area='Свободное место на земле', duration='1 час', components=array['В','С','М'], material='кусочек нити и дерева', check_type='', damage='', effect_summary='Создаёт невидимую бесформенную Среднюю силу, которая выполняет простые поручения. КД 10, 1 хит, Сила 2, атаковать не может.', upcast='', notes='Ритуал. Бонусным действием раз за ход можно приказать слуге переместиться на 15 футов и взаимодействовать с предметом. Если задание уведёт его дальше 60 футов от тебя, заклинание заканчивается.', author_description='Невидимый, безмозглый работник, который убирает, чинит, складывает вещи, разливает напитки и не спорит. После нескольких походов начинаешь понимать, почему это заклинание пережило века.', author_comment='Наконец-то член группы, которому можно поручить простую задачу и получить именно простой результат.' where slug='unseen-servant';